\label{thm:kron}
If $\alpha_1,\ldots,\alpha_r$ are arbitrary real numbers and $1,\lambda_1,\ldots,\lambda_r$ are real numbers linearly independent over $\mathbb{Q}$, then for $\epsilon>0$, there exist integers $q,p_1,\ldots,p_r$ such that for all $j\in\{1,\ldots,r\}$,
\begin{center}
$|q\lambda_j-p_j-\alpha_j|<\epsilon$.
\end{center}

\label{thm:pgst}
Suppose $u$ and $v$ are strongly cospectral vertices in $X$.
\begin{enumerate}
\item If ${\Phi}_{u}$ is a linearly independent set over $\mathbb{Q}$, then PGST occurs between $u$ and $v$ in $X$.
\item If $M=A$, $X$ is bipartite and ${\Phi}_{u}\cap\mathbb{R}^+$ is a linearly independent set over $\mathbb{Q}$, then PGST occurs between $u$ and $v$.
\end{enumerate}
Moreover, for any rational number $c>0$, PGST occurs between $u$ and $v$  relative to a sequence $\{\tau_m\}\subseteq (\frac{2\pi}{c})\mathbb{Z}$ in 1 or 2 when $u$ and $v$ are in the same parts. In particular, we may choose $\{\tau_m\}\subseteq 2\pi\mathbb{Z}$.

Let $u$ and $v$ be strongly cospectral in $X$ and $c>0$ be rational. From \cite{Banchi2017}, PGST occurs between $u$ and $v$ if and only if for each $\epsilon>0$, there exists $\tau\in\mathbb{R}$ such that for all $\lambda,\eta\in{\Phi}_{u,v}^+$ and $\theta\in{\Phi}_{u,v}^-$,
\begin{equation}
\label{eq:pgstchar}
|\tau (\lambda-\eta)|<\epsilon\pmod{2\pi}\quad \text{and}\quad |\tau (\lambda-\theta)-\pi|<\epsilon\pmod{2\pi}
\end{equation}

To prove 1, suppose that ${\Phi}_{u}$ is a linearly independent set over $\mathbb{Q}$ and fix $\lambda\in{\Phi}_{u,v}^+$. Then the set $\{\frac{1}{c}(\lambda-\mu):\mu\in {\Phi}_u\backslash\{\lambda\}\}$ is also linearly independent over $\mathbb{Q}$. Thus, for each $\epsilon>0$, Theorem~\ref{thm:kron} implies that there exist integers $q,p_\lambda,p_\theta$ such that $\left|\frac{q}{c}(\lambda-\eta)-p_\eta\right|<\frac{\epsilon}{2\pi}$ and $\left|\frac{q}{c}(\lambda-\theta)-p_\theta-\frac{1}{2}\right|<\frac{\epsilon}{2\pi}$ both hold modulo $2\pi$
for all $\eta\in{\Phi}_{u,v}^+$ and $\theta\in{\Phi}_{u,v}^-$. Equivalently, 
\begin{center}
$\left|(2\pi q/c)(\lambda-\eta)- 2\pi p_\lambda\right|<\epsilon\quad $ and $\quad \left|(2\pi q/c)(\lambda-\theta)-2\pi p_\theta-\pi\right|<\epsilon$
\end{center}
modulo $2\pi$. Thus, for each $\epsilon>0$, (\ref{eq:pgstchar}) has a solution $\tau=2\pi q/c$ for some integer $q$, implying that PGST occurs between $u$ and $v$ in $X$ relative to a sequence $\{\tau_m\}\subseteq (2\pi/c)\mathbb{Z}$. This proves 1.

To prove 2, let $M=A$, $X$ be bipartite and ${\Phi}_{u}\cap\mathbb{R}^+$ be a linearly independent set over $\mathbb{Q}$. Define $S^+={\Phi}_{u,v}^+\cap \mathbb{R}^+$ and $S^-={\Phi}_{u,v}^-\cap \mathbb{R}^+$. First, let $u$ and $v$ be in the same parts in $X$. As $X$ is bipartite, the form of eigenvectors of $\lambda$ and $-\lambda$ implies that ${\Phi}_{u,v}^+$ and ${\Phi}_{u,v}^-$ are closed under multiplication by $-1$. So, if $\lambda\in S^+$ is fixed, then (\ref{eq:pgstchar}) is equivalent to
\begin{equation}
\label{eq:pgstchar1}
|\tau(\lambda-\eta)|<\epsilon,\quad 
|\tau(2\lambda)|<\epsilon\quad \text{and}\quad |\tau(\lambda-\theta)-\pi|<\epsilon 
\end{equation}
modulo $2\pi$ for all $\eta\in S^+$ and $\theta\in S^-$. We claim that $\{\lambda-\eta:\lambda\neq\eta\in S^+\}\cup \{\lambda-\theta:\theta\in S^-\}\cup\{2\lambda\}$ is also a linearly independent set over $\mathbb{Q}$. To see this, if $a_\eta,b_\theta,c$ are integers such that
\begin{equation*}
\sum_{\lambda\neq \eta\in S^+}a_\eta(\lambda-\eta)+ \sum_{\theta\in S^-}b_\theta(\lambda-\theta)+c(2\lambda)=0,
\end{equation*}
then rewriting this equation and and using the fact that ${\Phi}_{u}\cap\mathbb{R}^+$ is a linearly independent set over $\mathbb{Q}$ yields $a_\eta=0$ for all $\eta\neq \lambda$, $b_\theta=0$ for all $\theta$, and $c=0$. This proves the claim. Applying the same argument as in 1, there exist integers $q,p_\lambda,p_\theta$ such that modulo $2\pi$, we have
\begin{center}
$\left|(2\pi q/c)(\lambda-\eta)- 2\pi p_\lambda\right|<\epsilon,\quad $ $\left|(2\pi q/c)(2\lambda)\right|<\epsilon\quad$ and $\quad\left|(2\pi q/c)(\lambda-\theta)-2\pi p_\theta-\pi\right|<\epsilon$
\end{center}
for all $\eta\in S^+$ and $\theta\in S^-$. Thus, for each $\epsilon>0$, (\ref{eq:pgstchar1}) has a solution $\tau=\frac{2\pi q}{c}$ for some integer $q$. Since (\ref{eq:pgstchar1}) is equivalent to (\ref{eq:pgstchar}), $\tau=\frac{2\pi q}{c}$ is also a solution to (\ref{eq:pgstchar1}), implying that PGST occurs between $u$ and $v$ in $X$ relative to a sequence $\{\tau_m\}\subseteq (\frac{2\pi}{c})\mathbb{Z}$. Next, suppose $u$ and $v$ are in the same parts in $X$. As $X$ is bipartite, the form of eigenvectors of $\lambda$ and $-\lambda$ implies that
$\lambda\in {\Phi}_{u,v}^+$ if and only of $-\lambda\in {\Phi}_{u,v}^-$. Thus, for a fixed $\lambda\in S^+$, (\ref{eq:pgstchar}) is equivalent to
\begin{equation*}
|\tau (\lambda-\eta)|<\epsilon,\quad |\tau (\lambda+\theta)|<\epsilon,\quad |\tau (\lambda+\eta)-\pi|<\epsilon,\quad \text{and}\quad |\tau (\lambda-\theta)-\pi|<\epsilon.
\end{equation*}
modulo $2\pi$ for all $\eta\in S^+$ and $\theta\in S^-$. Now, if $a_\eta,b_\theta,c_\eta,d_\theta$ are integers such that
\begin{center}
$\displaystyle\sum_{\eta\in S^+\backslash\{\lambda\}} a_\eta(\lambda-\eta)+\displaystyle\sum_{\theta\in S^-\backslash\{\lambda\}} b_\theta(\lambda+\theta)+\displaystyle\sum_{\eta\in S^+\backslash\{\lambda\}} c_\eta(\lambda+\eta)+\displaystyle\sum_{\theta\in S^-\backslash\{\lambda\}} d_\theta(\lambda-\theta)=0$, 
\end{center}
then, as ${\Phi}_{u}\cap\mathbb{R}^+$ is linearly independent over $\mathbb{Q}$, $a_\eta=c_\eta$, $b_\theta=d_\theta$ and
$2\displaystyle\sum_{\eta\in S^+\backslash\{\lambda\}} a_\eta + 2\displaystyle\sum_{\theta\in S^-\backslash\{\lambda\}} b_\theta=0$. Applying \cite[Lemma 1]{kempton2017pretty}, we obtain PGST between $u$ and $v$.

\label{ex:path2}
Let $M=A$. We show that $P_4$ admits PGST between end vertices $u$ and $v$ relative to $\{\tau_m\}\subseteq (2\mathbb{Z}+1)\pi$. Note that $u$ and $v$ belong to different parts, and the positive eigenvalues of $P_4$ are linearly independent over $\mathbb{Q}$. PGST occurs between $u$ and $v$ in $P_4$ if and only if
\begin{center}
$e^{i\tau(\frac{1+\sqrt{5}}{2})}\approx e^{i\tau(\frac{1-\sqrt{5}}{2})}\approx-e^{i\tau(\frac{-1+\sqrt{5}}{2})}\approx-e^{-i\tau(\frac{1+\sqrt{5}}{2})}$.
\end{center}
Equivalently, $e^{i\tau(1+\sqrt{5})}\approx e^{i\tau}\approx-e^{i\tau\sqrt{5}}\approx-1$, which holds if and only if for each $\epsilon>0$, $|t-\pi|<\epsilon$ and $|\sqrt{5}t|<\epsilon$ both have a solution modulo $2\pi$. Since $1$ and $\sqrt{5}$ are linearly independent over $\mathbb{Q}$, Theorem~\ref{thm:kron} yields a solution to this system. So PGST occurs between $u$ and $v$ in $P_4$ relative to $\{\tau_m\}\subseteq (2\mathbb{Z}+1)\pi$.

\label{thm:sed}
If $(E_{\theta})_{u,u}>\frac{1}{2}$, 
then $u$ is sedentary in $X$ with $|U_X(t)_{u,u}|\geq 2(E_{\theta})_{u,u}-1$.

\label{prop:sedpeak}
Let $u,v$ be two vertices in $X$. If vertex $u$ is $C$-sedentary, then $|U_X(t)_{u,v}|\leq \sqrt{1-C^2}$ for all $t\in\mathbb{R}$. Additionally, if peak state transfer occurs between $u$ and $v$ in $X$ at time $\tau$, then for all $t\in\mathbb{R}$,
\begin{center}
$|U_X(t)_{u,v}|\leq |U_X(\tau)_{u,v}|=B(X)_{u,v}\leq \sqrt{1-C^2}$.
\end{center}

\label{ex:sedpeakst}
For $n\geq 1$, let $G_n$ be the graph obtained from $K_{2,n}$ by attaching a pendent vertex to each vertex in the part of size $n$. Let $u$ and $v$ be the twins in $G_n$ as depicted in Fig.~\ref{fig:Gn}. In \cite[Section~6.2]{coutinho2025peak}, it was shown that peak state transfer occurs between $u$ and $v$ in $G_n$ with $B(G_n)_{u,v}=\frac{2n}{2n+1}$. It was also shown that the spectral idempotent $E_0$ for $G_n$ satisfies $(E_0)_{u,u}=(E_0)_{v,v}=\frac{n+1}{2n+1}>\frac{1}{2}$. By Theorem
\ref{thm:sed}, 
$u$ and $v$ are $C(n)$-sedentary in $G_n$ for all $n\geq 1$, where $C(n)=\frac{1}{2n+1}$. As $n\rightarrow\infty$, we get
\begin{center}
    $1\leq \frac{\sqrt{1-C(n)^2}}{B(G_n)_{u,v}}=\frac{\sqrt{1-1/(2n+1)^2}}{2n/(2n+1)}=                                         
\frac{\sqrt{n(n+1)}}{n}\rightarrow 1.$
\end{center}

\label{thm:peakstjoin}
Let $M\in\{A,L\}$ and consider $X\vee Y$, where we assume that $X,Y$ are $k$- and $\ell$-regular graphs, respectively, whenever $M=A$. If $u,v\in V(X\vee Y)$, then the following hold.
\begin{enumerate}
\item Suppose that peak state transfer occurs between $u$ and $v$ in $X$ at time $\tau$. If $M=A$, then peak state transfer occurs between $u$ and $v$ in $X\vee Y$ at time $\tau$ if and only if $e^{i\tau \lambda^+}=e^{i\tau \lambda^-}=e^{i\tau k}$ (equivalently, $\{k,\lambda^+,\lambda^-\}$ satisfies the ratio condition and $\lambda^+,\lambda^-$ are integers if $k\neq \ell$), in which case $U_{X\vee Y}(\tau)_{u,v}=e^{i\tau k}B(X)_{u,v}$. If $M=L$, then peak state transfer occurs between $u$ and $v$ in $X\vee Y$ at time $\tau$ if and only if $\tau=\frac{2r\pi}{\operatorname{gcd}(n_1,n_2)}$ for some integer $r$, in which case $U_{X\vee Y}(\tau)_{u,v}= B(X)_{u,v}$.
\item Suppose PGST occurs between $u$ and $v$ in $X$ relative to $\{\tau_m\}$. If $M=A$, then PGST occurs between $u$ and $v$ in $X\vee Y$ at time $\tau$ if and only if $\lim_{m\rightarrow\infty}e^{i\tau_m\lambda^+}=\lim_{m\rightarrow\infty}e^{i\tau_m\lambda^-}=\lim_{m\rightarrow\infty}e^{i\tau_mk}=\gamma$, in which case $\lim_{m\rightarrow\infty}U_{X\vee Y}(\tau_m)_{u,v}=\gamma$. If $M=L$, then PGST occurs between $u$ and $v$ in $X\vee Y$ at time $\tau$ if and only if $\lim_{m\rightarrow\infty}e^{i\tau_m n}=\lim_{m\rightarrow\infty}e^{i\tau_m n_2}=1$, in which case $\lim_{m\rightarrow\infty}U_{X\vee Y}(\tau_m)_{u,v}=1$.
\end{enumerate}

To prove 1, let $u,v\in V(X)$ and suppose that peak state transfer occurs between $u$ and $v$ in $X$ at time $\tau$. Then $U_X(\tau)_{u,v}=\gamma B(X)_{u,v}$ for some unit complex number $\gamma$. For $M=A$, we have $\gamma=e^{i\tau k}$. Since $U_X(\tau)_{u,v}=e^{i\tau k}B(X)_{u,v}$, (\ref{eq:joinA}) implies that $|U_{X\vee Y}(\tau)_{u,v}|$ equals
\begin{center}
$\big|\frac{e^{i\tau\lambda^+}(k-\lambda^-)}{n_1\sqrt{\Delta}}-\frac{e^{i\tau\lambda^-}(k-\lambda^+)}{n_1\sqrt{\Delta}}+e^{i\tau k}\big(B(X)_{u,v}-\frac{1}{n_1}\big)\big|
\leq \frac{k-\lambda^-}{n_1\sqrt{\Delta}}-\frac{k-\lambda^+}{n_1\sqrt{\Delta}}+B(X)_{u,v}-\frac{1}{n_1},$
\end{center}
where the right-hand side equals $B(X)_{u,v}$. Thus, $U_{X\vee Y}(\tau)_{u,v}=B(X)_{u,v}$ if and only if $e^{i\tau \lambda^+}=e^{i\tau \lambda^-}=e^{i\tau k}$. Equivalently, $\{k,\lambda^+,\lambda^-\}$ satisfies the ratio condition, in which case $\lambda^+$ and $\lambda^-$ are integers if $k\neq \ell$. 
Now, if $M=L$, then $\gamma=1$. Since $U_X(\tau)_{u,v}= B(X)_{u,v}$, (\ref{eq:joinL}) implies that $|U_{X\vee Y}(\tau)_{u,v}|$ equals
\begin{center}
$\big|\frac{1}{n}+\frac{n_2e^{i\tau n}}{n_1n}+e^{i\tau n_2}\big(B(X)_{u,v}-\frac{1}{n_1}\big)\big|\leq \frac{1}{n}+\frac{n_2}{n_1n}+B(X)_{u,v}-\frac{1}{n_1}=B(X)_{u,v}$.
\end{center}
Thus, $U_{X\vee Y}(\tau)_{u,v}=B(X)_{u,v}$ if and only if $e^{i\tau n}=e^{i\tau n_2}=1$, i.e. $\tau$ is an integer multiple of $\frac{2\pi}{\operatorname{gcd}(n_1,n_2)}$.
Combining these two cases with Lemma~\ref{lem:joinbound} yields 1. The proof of 2 follows from 1 by replacing $e^{i\tau k}$, $e^{i\tau \lambda^+}$ and $e^{i\tau \lambda^-}$ with $\lim_{m\rightarrow\infty}e^{i\tau_mk}$, $\lim_{m\rightarrow\infty}e^{i\tau_m\lambda^+}$ and $\lim_{m\rightarrow\infty}e^{i\tau_m\lambda^-}$ respectively when $M=A$, and replacing $e^{i\tau n}$ and $e^{i\tau n_2}$ with $\lim_{m\rightarrow\infty}e^{i\tau_mn}$ and $\lim_{m\rightarrow\infty}e^{i\tau_mn_2}$ respectively when $M=L$.

\label{thm:peakstjoin1}
Let $u\in V(X)$ and $v\in V(Y)$.
With the assumption in Theorem~\ref{thm:peakstjoin}, we have $U_{X\vee Y}(t)_{u,v}=\frac{e^{it\lambda^+}}{\sqrt{\Delta}}(1-e^{-it\sqrt{\Delta}})$ if $M=A$ and $U_{X\vee Y}(t)_{u,v}=\frac{1}{n}(1-e^{itn})$, otherwise. Thus, peak state transfer occurs between $u$ and $v$ in $X\vee Y$, where $U(\frac{\pi}{\sqrt{\Delta}})_{u,v}=\frac{2e^{i\tau\lambda^+}}{\sqrt{\Delta}}$ if $M=A$ and $U(\frac{\pi}{n})_{u,v}=\frac{2}{n}$ if $M=L$. Moreover, PGST does not occur between $u$ and $v$ in $X\vee Y$.

Let $X$ be the Petersen graph, which is a 3-regular graph on 10 vertices. Let $u$ and $v$ be adjacent vertices in $X$. Then $X$ admits peak state transfer between $u$ and $v$ relative to $A$ at time $\tau=\pi$ with $|U_{X}(\tau)_{u,v}|=\frac{8}{15}$ \cite[Section 6.1]{coutinho2025peak}. Since $X$ is regular, this also holds relative to $L$. 
\begin{itemize}
\item Since $\tau=\pi$, Theorem~\ref{thm:peakstjoin}(1) yields peak state transfer in $X\vee Y$  between $u$ and $v$ relative to $L$ at time $\tau$ if and only if $Y$ has an even number of vertices.
\item Let $Y$ be an $\ell$-regular with $n$ vertices. Since $e^{i\tau k}=-1$ Theorem~\ref{thm:peakstjoin}(1) yields peak state transfer relative to $A$ between $u$ and $v$ in $X\vee Y$ at time $\tau$ if and only if $e^{i\tau \lambda^+}=e^{i\tau \lambda^-}=-1$. That is, $\lambda^{\pm}=\frac{1}{2}(3+\ell\pm\sqrt{(\ell-3)^2+40n})$ are odd integers. There are many such graphs $Y$, for example we may take $\ell=3$ and $n=10s^2$ for any integer $s\geq 1$, in which case $\lambda^{\pm}=3\pm 10s$ are both even.
\end{itemize}

\label{lem:cartbound}
Let $M\in\{A,L\}$ and consider $X\square Y$. If $u,v\in V(X)$ and $x,y\in V(Y)$, then
\begin{center}
$B(X\square Y)_{(u,x),(v,y)}\leq B(X)_{u,v}\cdot B(Y)_{x,y}.$
\end{center}

For each $\lambda\in{\mathrm{spec}}(M(X\square Y))$, (\ref{eq:cartE}) and the triangle inequality give us
\begin{center}
$B(X\square Y)_{(u,x),(v,y)}=\displaystyle\sum_{\lambda\in{\mathrm{spec}}(M(X\square Y))}|(E_\lambda)_{(u,x),(v,y)}|\leq \sum_{\mu\in{\mathrm{spec}}(M(X))}\sum_{\theta\in{\mathrm{spec}}(M(Y))}|(E_{\mu})_{u,v}|\cdot |(E_{\theta})_{x,y}|.$
\end{center}
Since we may write the rightmost expression as $B(X)_{u,v}\cdot B(Y)_{x,y}$, we get the desired conclusion.

\label{thm:peakstcartprod}
Suppose $X$ admits peak state transfer between $u$ and $v$ at time $\tau$.
\begin{enumerate}
\item If $Y$ admits peak state transfer between $x$ and $y$ at time $\tau$, then $X\square Y$ has peak state transfer between $(u,x)$ and $(v,y)$ at time $\tau$. In this case, $|U_{X\square Y}(\tau)_{(u,x),(v,y)}|=B(X)_{u,v}\cdot B(Y)_{x,y}.$
\item If $x$ is periodic in $Y$ at time $\tau$, then $X\square Y$ admits peak state transfer between $(u,x)$ and $(v,x)$ at time $\tau$. In this case, $|U_{X\square Y}(\tau)_{(u,x),(v,x)}|=B(X)_{u,v}.$
\end{enumerate}

Suppose $X$ admits peak state transfer between $u$ and $v$ at time $\tau$. From (\ref{eq:cartprod}), we have 
\begin{center}
$|U_{X\square Y}(\tau)_{(u,x),(v,y)}|=|U_X(\tau)_{u,v}|\cdot |U_Y(\tau)_{x,y}|=B(X)_{u,v}\cdot |U_Y(\tau)_{x,y}|.$
\end{center}
So, if $Y$ admits peak state transfer between $x$ and $y$ at time $\tau$, the above equation and (\ref{eq:bounding}) yields 
\begin{center}
$B(X)_{u,v}\cdot B(Y)_{x,y}=|U_{X\square Y}(\tau)_{(u,x),(v,y)}|\leq B(X\square Y)_{(u,x),(v,y)}.$
\end{center}
Combining this with Proposition~\ref{lem:cartbound} yields $|U_{X\square Y}(\tau)_{(u,x),(v,y)}|=B(X)_{u,v}\cdot B(Y)_{x,y}=B(X\square Y)_{(u,x),(v,y)}.$ This proves 1, while 2 follows similarly.

\label{thm:pgstcartprod}
Suppose $X$ admits PGST between $u$ and $v$ relative to $\{\tau_m\}$.
\begin{enumerate}
\item There is PGST or PST between $x$ and $y$ in $Y$ relative to $\{\tau_m\}$ if and only if $X\square Y$ has PGST between $(u,x)$ and $(v,y)$ relative to $\{\tau_m\}$. 
\item A vertex $x$ is almost periodic or periodic in $Y$ relative to $\{\tau_m\}$ if and only if $X\square Y$ has PGST between $(u,x)$ and $(v,x)$ relative to $\{\tau_m\}$. 
\end{enumerate}

If $X$ has PGST between $u$ and $v$ in $X$ relative to $\{\tau_m\}$, then $\displaystyle\lim_{m\rightarrow\infty}$$|U_X(\tau_m)_{u,v}|=1$. Applying (\ref{eq:cartprod}), 
\begin{center}
$\displaystyle\lim_{m\rightarrow\infty}$$|U_{X\square Y}(\tau_m)_{(u,x),(v,y)}|=$ $\displaystyle\lim_{m\rightarrow\infty}$$|U_X(\tau_m)_{u,v}|\cdot $ $\displaystyle\lim_{m\rightarrow\infty}$$|U_Y(\tau_m)_{x,y}|=$$\displaystyle\lim_{m\rightarrow\infty}$$|U_Y(\tau_m)_{x,y}|$.
\end{center}
From this, 1 follows immediately, while 2 is straightforward from taking $x=y$.

Let $M\in\{A,L\}$ and suppose $X$ admits PGST between $u$ and $v$ relative to $\{\tau_m\}$.
\begin{enumerate}
\item Suppose $\{\tau_m\}\subseteq 2\pi\mathbb{Z}$. If $Y$ is an integral graph, then $X\square Y$ admits PGST between $(u,x)$ and $(v,y)$ relative to $\{\tau_m\}$ for all $x,y\in V(Y)$ relative to $\{\tau_m\}$. For example, if $M=A$, $P_n$ is a path with $n\in \{2^t,2p\}$, and $Y$ is an integral graph, then the preceding observation combined with Example~\ref{ex:path1} yields PGST in $P_n\square Y$ between $(u,x)$ and $(n+1-u,x)$ relative to $\{\tau_m\}$ for all $x,y\in V(Y)$.


\item Suppose $\{\tau_m\}\subseteq (2\mathbb{Z}+1)\frac{\pi}{2}$. If $Y$ admits PST between $u$ and $v$ at time $\frac{\pi}{2}$, then $X\square Y$ admits PGST between $(u,x)$ and $(v,x)$ relative to $\{\tau_m\}$. For example, if $X\in \{\operatorname{Cay}(\mathbb{Z}_n,S\cup\{\frac{n}{2}\}),\operatorname{Cay}(\mathbb{Z}_n,S\cup\{\frac{n}{4},\frac{3n}{4}\})\}$ as in Example~\ref{ex:Cn1}, and $Y=H(d,2)$, then our preceding observation yields PGST in $X\square Y$ between $(u,x)$ and $(u+\frac{n}{2},y)$ relative to $\{\tau_m\}$ for any pair of antipodal vertices $x$ and $y$ in $Y$.
\end{enumerate}

\label{prop:XXbar}
Let $X$ be a graph on $n$ vertices. For all $t\in\mathbb{R}$, we have  
\begin{equation*}
U_{X^c}(t)
=
  \begin{cases}
    e^{-it}U_{X}(-t)+\left(\frac{e^{-it(k+1)}(e^{itn}-1)}{n}\right)\mathbf{J} & \text{if $M=A$ and $X$ is regular},\\
    e^{itn}U_{X}(-t)+\left(\frac{1-e^{itn}}{n}\right)\mathbf{J} & \text{if $M=L$}.
  \end{cases}
\end{equation*}

Since $L(X^c)=nI-\mathbf{J}-L(X)$ and the matrices $nI$, $\mathbf{J}$, and $L(X)$ pairwise commute, we obtain $U_{X^c}(t)=e^{itn}e^{-it\mathbf{J}}e^{-itL(X)}=e^{itn}e^{-it\mathbf{J}}U_{X}(-t).$ Combining this with $e^{-it\mathbf{J}}=I+\left(\frac{e^{-itn}-1}{n}\right)\mathbf{J}$ gives us
\begin{center}
$U_{X^c}(t)=\left(e^{itn}I+\left(\frac{1-e^{itn}}{n}\right)\mathbf{J}\right)U_{X}(-t).$
\end{center}
Finally, since $\frac{1}{n}\mathbf{J}$ is a spectral idempotent for $L$, we get $\mathbf{J}U_{X}(-t)=U_{X}(-t)\mathbf{J}=\mathbf{J}$. Hence, the conclusion for $M=L$ is immediate from the above equation. The case $M=A$ and $X$ is regular follows similarly.

\label{cor:comppgstpeak}
Let $u$ and $v$ be two vertices in $X$ such that $B(X)_{u,v}=B(X^c)_{u,v}$.
If (i) $M=A$ and $X$ is regular or (ii) $M=L$, then the following hold.
\begin{enumerate}
\item If $X$ admits PGST between $u$ and $v$ relative to a sequence $\{\tau_m\}$, then $X^c$ admits PGST between $u$ and $v$ relative to the same sequence if and only if $\lim_{m\rightarrow\infty}n\tau_m\equiv 0\pmod{2\pi}$. 
\item If $X$ admits peak state transfer between $u$ and $v$ at time $\tau$, then $X^c$ also admits peak state transfer between $u$ and $v$ at the same time if and only if $n\tau\equiv 0\pmod{2\pi}$, in which case $U_{X^c}(t)_{u,v}=e^{-it}\overline{U_{X}(t)_{u,v}}$ and $|U_{X^c}(t)_{u,v}|=|U_{X}(t)_{u,v}|=B(X)_{u,v}$. In particular, if $X$ admits PST between $u$ and $v$ at time $\tau$ and $n\tau\equiv 0\pmod{2\pi}$, then $X^c$ admits PST between $u$ and $v$ at time $\tau$.
\end{enumerate}

\label{ex:2ex}
The following statements hold by Corollary~\ref{cor:comppgstpeak}(2).
\begin{itemize}
\item Let $n\equiv 0\pmod{4}$ so that $X=K_2\square K_n$ is a coconnected regular graph with PST at time $\frac{\pi}{2}$. Then $X^c$ is the direct product of $K_2$ and $K_n$, which has PST at $\frac{\pi}{2}$ between the same pairs of vertices.
\item Let $X$ be the Petersen graph, which is a coconnected 3-regular graph on 10 vertices and admits peak state transfer at time $\pi$. Then $X^c$ is the Johnson graph $J(5,2)$ which has peak state transfer at $\pi$.
\end{itemize}

\label{prop:regupperbound2}
For all $u,v\in V(X)$ and for all $t\in\mathbb{R}$, we have 
\begin{center}
$g_{u,v}(t)\leq b\leq 1\quad $ and $\quad f_{u,v}(t)\leq B(X)_{u,v}+B(X^c)_{u,v}
\leq 2$,
\end{center}
where $b=\max\{B(X)_{u,v}, B(X^c)_{u,v}\}$. In particular, if $b=B(X)_{u,v}$, then $g_{u,v}(\tau)=b$ if and only if $X$ admits peak state transfer between $u$ and $v$ at time $\tau$ and $U_{X^c}(\tau)_{u,v}=0$.

\label{prop:regupperbound1}
For all $u,v\in V(X)$, we have 
$g_{u,v}(t)\leq f_{u,v}(t)$ for all $t\in\mathbb{R}$.

\label{eq:corfg}
Let $X$ be graph on $n$ vertices. If (i) $M=A$ and $X$ is regular or (ii) $M=L$, then:
\begin{enumerate}
\item If $\tau=2j\pi/n$ for any integer $j$, then $|U_{X^c}(\tau)_{u,v}|=|U_X(\tau)_{u,v}|$ for all $u,v\in V(X)$.
\item                                                                                                   
If PGST occurs between $u$ and $v$ in $X$ relative to $\{\tau_m\}$, then $\liminf_{m\rightarrow\infty}|U_{X^c}(\tau_m)_{u,v}|\geq 1-\frac{2}{n}$. If peak state transfer occurs between $u$ and $v$ in $X$ at time $\tau$, then $|U_{X^c}(\tau)_{u,v}|\geq B(X)_{u,v}-\frac{2}{n}$.
\end{enumerate}

\label{cor:joinfuvupperbound}
Let $X$ be a join graph on $n$ vertices with $u,v\in V(X)$. 
\begin{enumerate}
\item If $u$ and $v$ are in different components in $X^c$, then $g_{u,v}(t)=f_{u,v}(t)=|U_X(t)_{u,v}|\leq \frac{2}{n}$ for all $t\in\mathbb{R}$.

\item If $M=L$ and $u$ is an isolated vertex in $X^c$, then $|U_X(t)_{u,u}|\geq 1-\frac{2}{n}$ for all $t\in\mathbb{R}$. In particular, $u$ is sedentary in $X$ whenever $n\geq 3$.
\end{enumerate}

\label{lem: transition_difference}
Let $\{\mathbf{v}_1,\dots, \mathbf{v}_m,\mathbf{v}_{m+1}\dots,\mathbf{v}_n\}$ and  $\{\mathbf{u}_1,\dots,\mathbf{u}_m,\mathbf{v}_{m+1}\dots,\mathbf{v}_n\}$ be orthonormal bases of eigenvectors of $A(X)$ and $A(X^c)$ respectively, where $\mathbf u_j, \mathbf v_j$ are main for all $j\in\{1,\ldots,m\}$ and non-main otherwise. Then
    \begin{equation*}
    U_{X^c}(t)-e^{-it}U_X(-t) = \sum_{j = 1}^m\big(e^{it\lambda_j}\mathbf{u}_j\mathbf{u}_j^\top - e^{-it(1+\eta_j)}\mathbf{v}_j\mathbf{v}_j^\top\big)\quad \text{for all $t\in\mathbb{R}$},
\end{equation*}
where $\lambda_j$ and $\eta_j$ are the main eigenvalues of $A(X^c)$ and $A(X)$ corresponding to $\mathbf{u}_j$ and $\mathbf{v}_j$, respectively.

Observe that
\begin{equation*}
    U_X(t) = \sum_{j = 1}^me^{it\eta_j}\mathbf{v}_j\mathbf{v}_j^\top + \sum_{j=m+1}^ne^{it(\eta_j)}\mathbf{v}_j\mathbf{v}_j^\top.
\end{equation*}
By Proposition~\ref{prop:main}, $\mathbf{v}_j$ is a non-main eigenvector of $A(X)$ with eigenvalue $\eta_j$ if and only if $\mathbf v_j$ is a non-main eigenvector of $A(X^c)$ with eigenvalue $-(1+\eta_j)$. Consequently, 
\begin{equation*}
    U_{X^c}(t)= \sum_{i = j}^me^{it\lambda_j}\mathbf{u}_j\mathbf{u}_j^\top + \sum_{j=m+1}^ne^{-it(1+\eta_j)}\mathbf{v}_j\mathbf{v}_j^\top
\end{equation*}
The claim then follows.

\label{thm:nonreguv}
Let $X$ be a graph on $n$ vertices with average degree $d_{avg}$. If $A(X)$ has exactly two linearly independent main eigenvectors, then for all $u,v\in V(X)$,
    \[f_{u,v}(t) \leq \frac{2}{n}\sqrt{\bigg(1+\frac{n(d_u-d_{avg})^2}{\sum_{w\in V(X)}(d_w-d_{avg})^2}\bigg)\bigg(1+\frac{n(d_v-d_{avg})^2}{\sum_{w\in V(X)}(d_w-d_{avg})^2}\bigg)},\quad \text{for all $t\in\mathbb{R}$}.\]

\label{prop:NG}
Let $X$ be a graph with $u,v\in V(X)$. Then for all $t\in\mathbb{R}$, 
\begin{equation}
\label{eq:peakst1}
\sigma_{u,v}(t)\leq B(X)_{u,v}+B(X^c)_{u,v}\quad \text{and}\quad \rho_{u,v}(t)\leq B(X)_{u,v}\cdot B(X^c)_{u,v}.
\end{equation}
Moreover, the following holds.
\begin{enumerate}
\item Let $X$ be coconnected. The following are equivalent: (i) peak state transfer occurs between $u$ and $v$ in $X$ and $X^c$ at time $\tau$, (ii) the equality holds for $\sigma_{u,v}(\tau)$ in (\ref{eq:peakst1}), and (iii) the equality holds for $\rho_{u,v}(\tau)$ in (\ref{eq:peakst1}). The following are also equivalent: (a) $u$ is periodic in $X$ and $X^c$ at time $\tau$, (b) $\sigma_{u,u}(\tau)=2$, and (c) $\rho_{u,u}(\tau)=1$. Moreover, the following are equivalent: (A) PGST occurs between $u$ and $v$ in $X$ and $X^c$ relative to the same sequence of times, (B) $\sup_{t>0}\sigma_{u,v}(t)=2$ and (C) $\sup_{t>0}\rho_{u,v}(t)=1$. Furthermore, the following are also equivalent: (I) $u$ is almost periodic in $X$ and $X^c$ relative to the same sequence of times, (II) $\sup_{t>0}\sigma_{u,u}(t)=2$ and (III) $\sup_{t>0}\rho_{u,u}(t)=1$.
\item Let $X$ be coconnected. If (i) $M=A$ and $X$ is regular or (ii) $M=L$, then $\sigma_{u,v}(t)\leq 2B(X)_{u,v}$ and $\rho_{u,v}(t)\leq (B(X)_{u,v})^2$ for all $t\in\mathbb{R}$.
\item Suppose $X^c$ is a disconnected graph on $n$ vertices where $u,v$ belong to different components in $X^c$. Then $\sigma_{u,v}(t)\leq B(X)_{u,v}$ and $\rho_{u,v}(t)=0$ for all $t\in\mathbb{R}$. In particular, we have $\sigma_{u,v}(t)\leq \frac{2}{\sqrt{\Delta}}$ if $M=A$ and $X$ is a join of two regular graphs, and $\sigma_{u,v}(t)\leq \frac{2}{n}$ if  $M=L$.
\end{enumerate}

\label{prop:NGsed}
Let $M\in\{A,L\}$ and $X$ be a graph with $u,v\in V(X)$ with $u\neq v$.
\begin{enumerate}
\item If $u$ is $C_1$-sedentary in $X$, then for all $t\in\mathbb{R}$,
\begin{equation}
\label{eq:NGsed}
