\label{thmspecdecombsg}
	Let $X$ be an $(\alpha,\beta)$-bidegreed split graph, where $C$ is the induced clique and $S$ is the induced independent set. Index the adjacency matrix so that $A(X)=\begin{bmatrix}
	\mathbf{J}_m-I_m & B \\ B^\top & O_n
	\end{bmatrix}$ where $m=|C|$, $n=|S|$,  $B\mathbf{1}_n=(\alpha-m+1)\mathbf{1}_m=k\mathbf{1}_m$, and $B^\top\mathbf{1}_m=\beta\mathbf{1_n}$. Then the spectral decomposition of $A(X)$ is given by
	\begin{equation*}
	A(X) =\lambda_1E_{\lambda_1}+\lambda_2E_{\lambda_2} + \displaystyle\sum_{\stackrel{\gamma\in \mathrm{nspec}(BB^\top)}{\lambda^2+\lambda-\gamma=0}} \lambda E_{\lambda,\gamma}
	\end{equation*}
	where $\lambda_i$, $i\in\{1,2\}$, satisfies $\lambda_i^2-(m-1)\lambda_i-\beta k=0$ and \begin{equation*}
	E_{\lambda_i}=\dfrac{1}{m\lambda_i^2+n\beta^2}\begin{bmatrix}
	\lambda_i^2 \mathbf{J} & \lambda_i \beta \mathbf{J} \\
	\lambda_i \beta \mathbf{J} & \beta^2\mathbf{J}
	\end{bmatrix},
	\end{equation*} and for $\gamma\neq0$,
	\begin{equation*}
	E_{\lambda,\gamma}=
		\displaystyle\sum_{\substack{\mathbf{1}^\top \mathbf{x}=\mathbf{0}, BB^\top \mathbf{x}=\gamma \mathbf{x}}}\dfrac{1}{\lambda^2+\gamma}\begin{bmatrix}
		\lambda^2 \mathbf{x}\mathbf{x}^\top &\lambda \mathbf{x}\mathbf{x}^\top B\\
		\lambda B^\top \mathbf{x}\mathbf{x}^\top & B^\top \mathbf{x}\mathbf{x}^\top B
		\end{bmatrix}=\sum_{\mathbf{1}^\top \mathbf{y}=\mathbf{0}, B^\top B\mathbf{y}=\gamma \mathbf{y}}\frac{\gamma}{\lambda^2+\gamma}\begin{bmatrix}
		\frac{\lambda^2}{\gamma^2}B\mathbf{y}\mathbf{y}^\top B & \frac{\lambda}{\gamma}B\mathbf{y}\mathbf{y}^\top \\ \frac{\lambda}{\gamma}\mathbf{y}\mathbf{y}^\top B & \mathbf{y}\mathbf{y}^\top
		\end{bmatrix}.
	\end{equation*}
	Moreover if $\gamma=0$ and $\lambda\in\{-1,0\}$, then
\begin{equation*}
E_{-1,0}=\displaystyle\sum_{\mathbf{1}^\top \mathbf{x}=BB^\top \mathbf{x}=\mathbf{0}}\begin{bmatrix}
\mathbf{x}\mathbf{x}^\top & O \\ O & O\end{bmatrix}\qquad\mbox{and}\qquad
E_{0,0}=\displaystyle\sum_{\mathbf{1}^\top \mathbf{y}=B^\top B\mathbf{y}=\mathbf{0}}\begin{bmatrix}
O & O \\ O & \mathbf{y}\mathbf{y}^\top\end{bmatrix}.
\end{equation*}

By Proposition 4.2 in \cite{goldberg2020onsplit}, the eigenvalues $\lambda$ of $A(X)$ satisfy one of the following: (i) $\lambda=0$, (ii) $\lambda^2-(m-1)\lambda-\beta k=0$, or (iii) $\lambda^2+\lambda-\gamma=0$ for some $\gamma\in\mathrm{nspec}(BB^\top)$. From the eigenequation $\begin{bmatrix}
\mathbf{J}_m-I_m & B \\ B^\top & {O}_n
\end{bmatrix}\begin{bmatrix}
\mathbf{x} \\ \mathbf{y}
\end{bmatrix}=\lambda\begin{bmatrix}
\mathbf{x} \\ \mathbf{y}
\end{bmatrix}$, we get the following system of equations:
\begin{equation}\label{eqeigen1}
(\lambda+1)\mathbf{x}-\mathbf{J}_m\mathbf{x}-B\mathbf{y}=\mathbf{0}\quad\text{and}\quad  
-B^\top \mathbf{x} +\lambda \mathbf{y}=\mathbf{0},
\end{equation}
which together simplify to \begin{equation}\label{eqeigen2}
(\lambda^2+\lambda)\mathbf{x}-\lambda \mathbf{J}_m\mathbf{x}-BB^\top \mathbf{x}=\mathbf{0}
\end{equation} when $\lambda\neq0$. If $\mathbf{x}=\mathbf{0}$, the above system implies $\lambda=0$. So, assume first that $\mathbf{x}\neq \mathbf{0}$ and $\mathbf{1}^\top \mathbf{x}\neq \mathbf{0}$. Pre-multiplying by $\mathbf{J}_m$, and then using the fact that $BB^\top\mathbf{1}_m=\beta k\mathbf{1}_m$ gives us
\begin{equation*}\label{eqeigen3}
(\lambda^2-(m-1)\lambda-\beta k)\mathbf{J}_m\mathbf{x}=\mathbf{0}.
\end{equation*} 
Thus, an eigenvector $\mathbf x$ satisfying $\mathbf{1}^\top \mathbf{x}\neq \mathbf{0}$ corresponds to the eigenvalue satisfying $\lambda^2-(m-1)\lambda-\beta k=0$. Observe also from \eqref{eqeigen2} that $\mathbf{x}$ must be an eigenvector of $\lambda \mathbf{J}_m+BB^\top$ and hence is a scalar multiple of $\mathbf{1}_m$ because $BB^\top$ is $\beta k$-stochastic and $\mathbf{1}^\top \mathbf{x}\neq \mathbf{0}$. (This is clear when $BB^\top$ is irreducible but can also be shown for the reducible case with a little more work.) It follows that an eigenvector of $A(X)$ corresponding to such an eigenvalue $\lambda$ is (a scalar multiple of) $\begin{bmatrix}
\lambda \mathbf{1} \\ \beta \mathbf{1}
\end{bmatrix}$ and the spectral idempotent is given by $\dfrac{1}{m\lambda^2+n\beta^2}\begin{bmatrix}
	\lambda^2 \mathbf{J} & \lambda \beta \mathbf{J} \\
	\lambda \beta \mathbf{J} & \beta^2\mathbf{J}
\end{bmatrix}$. Now, assuming that $\mathbf{x}\neq \mathbf{0}$ but $\mathbf{1}^\top \mathbf{x}=\mathbf{0}$, \eqref{eqeigen2} simplifies to $BB^\top \mathbf{x} = (\lambda^2+\lambda)\mathbf{x}$. Then, $\mathbf{x}$ must be an eigenvector of $BB^\top$ corresponding to $\gamma\in\mathrm{nspec}(BB^\top)$ and $\begin{bmatrix}
\lambda \mathbf{x} \\ B^\top \mathbf{x}
\end{bmatrix}$ is an eigenvector of $A(X)$ corresponding to $\lambda$ satisfying $\lambda^2+\lambda-\gamma=0$. Furthermore, the spectral idempotent for $\gamma\neq0$ is $E_{\lambda,\gamma}=
\displaystyle\sum_{\substack{\mathbf{1}^\top \mathbf{x}=\mathbf{0}, BB^\top \mathbf{x}=\gamma \mathbf{x}}}\dfrac{1}{\lambda^2+\gamma}\begin{bmatrix}
\lambda^2 \mathbf{x}\mathbf{x}^\top &\lambda \mathbf{x}\mathbf{x}^\top B\\
\lambda B^\top \mathbf{x}\mathbf{x}^\top & B^\top \mathbf{x}\mathbf{x}^\top B
\end{bmatrix}$. Taking $\mathbf{y}=B^\top \mathbf{x}$, the eigenvectors are of the form $\begin{bmatrix}
\frac{\lambda}{\gamma}B\mathbf{y} \\ \lambda \mathbf{y}
\end{bmatrix}$, and $E_{\lambda,\gamma}$ can be expressed equivalently as $\displaystyle\sum_{\mathbf{1}^\top \mathbf{y}=\mathbf{0}, B^\top B\mathbf{y}=\gamma \mathbf{y}}\frac{\gamma}{\lambda^2+\gamma}\begin{bmatrix}
\frac{\lambda^2}{\gamma^2}B\mathbf{y}\mathbf{y}^\top B & \frac{\lambda}{\gamma}B\mathbf{y}\mathbf{y}^\top \\ \frac{\lambda}{\gamma}\mathbf{y}\mathbf{y}^\top B & \mathbf{y}\mathbf{y}^\top
\end{bmatrix}$.

If $\gamma=0$, then $\lambda=-1$ or $\lambda=0$. For the case $\lambda=-1$, the eigenequation \eqref{eqeigen1} results in $B\mathbf{y} =\mathbf{0}$ and\linebreak $ B^\top \mathbf{x} + \mathbf{y}=\mathbf{0}$,
which implies that $BB^\top \mathbf{x} =\mathbf{0}$ and so $\mathbf{y}=-B^\top \mathbf{x}=\mathbf{0}$. Thus, $E_{-1,0}=\displaystyle\sum_{\mathbf{1}^\top \mathbf{x}=BB^\top \mathbf{x}=\mathbf{0}}\begin{bmatrix}
\mathbf{x}\mathbf{x}^\top & O \\ O & O\end{bmatrix}$. Similarly, when $\lambda=0$, the eigenequation \eqref{eqeigen1} simplifies to $B\mathbf{y} =\mathbf{x}$ and $ B^\top \mathbf{x}=\mathbf{0}$,
so $B^\top B \mathbf{y}=\mathbf{0}$ and $B\mathbf{y}=\mathbf{0}$. Thus,
$E_{0,0}=\displaystyle\sum_{\mathbf{1}^\top \mathbf{y}=B^\top B\mathbf{y}=\mathbf{0}}\begin{bmatrix}
O & O \\ O & \mathbf{y}\mathbf{y}^\top\end{bmatrix}.$

Let $X$ be a connected $(\alpha,\beta)$-bidegreed split graph where $|C|=n_1$ and $|S|=n_2$. Furthermore, suppose that $X$ is not the join of two regular graphs. The main eigenvalues of $A(X)$ are $\lambda_1,\lambda_2$ satisfying $\lambda_i^2-(n_1-1)\lambda_i-\beta k=0$. Note that $\lambda_1\neq \lambda_2$, so by Proposition~\ref{prop:2mainevec} $A(X)$ has exactly two linearly independent main eigenvectors. The graph $X$ then meets the hypotheses of Corollary~\ref{cor:twomain bidegree bound}, and so
    \[f_{u,v}(t)\leq \begin{cases}
        2/n_1, &u,v\in C\\
        2/n_2, &u,v\in S\\
        2/\sqrt{n_1n_2}, &\text{otherwise}.
    \end{cases}\]
    To compute $f_{u,v}(t)$ exactly, we use the spectral decomposition of $A(X)$ and $A(X^c)$. As stated in the proof of Theorem~\ref{thmspecdecombsg}, the associated eigenvectors of $\lambda_1,\lambda_2$ are $\begin{bmatrix}
        \lambda_i\mathbf 1 \\
        \beta \mathbf 1 
    \end{bmatrix}.$ The graph $X^c$ is disconnected only if $X$ is the join of two regular graphs, and therefore $X^c$ is a connected bidegreed split graph. Then $A(X^c)$ has two linearly independent main eigenvectors $\begin{bmatrix}
        \lambda_i^c\mathbf 1 \\
        \beta^c \mathbf 1 
    \end{bmatrix}$ where $\beta^c = (n_1+n_2-1-\alpha)$ and $\lambda_1^c,\lambda_2^c$ satisfy $(\lambda_i^c)^2-(n_2-1)\lambda_i^c-\beta^c(n_1-\beta)=0$. By Lemma~\ref{lem: transition_difference},
    \[U_{X^c}(t) - e^{-it}U_X(-t) = e^{it\lambda_1^c}E_{\lambda_1^c}+e^{it\lambda_2^c}E_{\lambda_2^c}-e^{-it(\lambda_1+1)}E_{\lambda_1} - e^{-it(\lambda_2+1)}E_{\lambda_2}\]
    where 
    \[E_{\lambda_i^c} = \frac{1}{n_2(\lambda_i^c)^2 + n_1(\beta^c)^2}\begin{bmatrix}
        (\beta^c)^2\mathbf{J} & \lambda_i^c\beta^c\mathbf{J}\\
        \lambda_i^c\beta^c\mathbf{J} & (\lambda_i^c)^2\mathbf{J}\\
    \end{bmatrix}.\]
    We thus obtain 
    \[f_{u,v}(t) =  \begin{cases}
        \left|\frac{e^{it\lambda_1^c}}{n_1+n_2(\lambda_1^c/\beta^c)^2} 
        + \frac{e^{it\lambda_2^c}}{n_1+n_2(\lambda_2^c/\beta^c)^2}
        -\frac{e^{-it(\lambda_1+1)}}{n_1+n_2(\beta/\lambda_1)^2}
        -\frac{e^{-it(\lambda_2+1)}}{n_1+n_2(\beta/\lambda_2)^2}\right|,& u,v \in C\\

        \left|\frac{e^{it\lambda_1^c}}{n_2+n_1(\lambda_1^c/\beta^c)^2} 
        + \frac{e^{it\lambda_2^c}}{n_2+n_1(\lambda_2^c/\beta^c)^2}
        -\frac{e^{-it(\lambda_1+1)}}{n_2+n_1(\beta/\lambda_1)^2}
        -\frac{e^{-it(\lambda_2+1)}}{n_2+n_1(\beta/\lambda_2)^2}\right|,& u,v \in C\\

        \left|\frac{e^{it\lambda_1^c}}{n_2\lambda_1^c/\beta^c + n_1\beta^c/\lambda_1^c} + \frac{e^{it\lambda_2^c}}{n_2\lambda_2^c/\beta^c + n_1\beta^c/\lambda_2^c}-\frac{e^{-it(\lambda_1+1)}}{n_1\lambda_1/\beta+n_2\beta/\lambda_1}-\frac{e^{-it(\lambda_2+1)}}{n_1\lambda_2/\beta+n_2\beta/\lambda_2}\right|,&\text{otherwise}.
    \end{cases}\]  

If one applies the triangle inequality and some natural upper bounds on the summands of $f_{u,v}(t)$, the upper bounds obtained for $f_{u,v}(t)$ above are twice those found using Corollary~\ref{cor:twomain bidegree bound}.

\label{thm:splitper}
Suppose $m\geq 2$. A bidegreed split graph $X$ with induced clique of size $m$ is periodic if and only if $(m-1)^2+4\beta k$ and $1+4\gamma$ are perfect squares for all $\gamma\in \mathrm{nspec}(BB^\top)$.

